/* Task-first workspace. Additive presentation layer; original v13 data retained.
   Role selection is a local demo preference, not authentication or authorization. */
(function () {
  'use strict';
  const U = AIM.ui, S = AIM.store, L = AIM.logic, C = AIM.config;
  const { esc, nf, pct } = U;
  const legacy = { dashboard: AIM.views.dashboard, usecases: AIM.views.usecases, prompts: AIM.views.prompts, skills: AIM.views.skills, agents: AIM.views.agents, libOpen: AIM.lib.open };
  C.tagline = 'Không gian ứng dụng AI · Ban Kiểm soát nội bộ';
  C.workspace = { id: 'ksnb', name: 'Ban Kiểm soát nội bộ', organization: 'PVEP', stage: 'Thí điểm tại Ban KSNB', ...C.workspace };
  const KEY = 'aim.workspace.v2';
  let pref = {};
  try { pref = JSON.parse(localStorage.getItem(KEY) || '{}') || {}; } catch (_) {}
  if (typeof pref !== 'object' || Array.isArray(pref)) pref = {};
  let current = { key: 'home', params: {} }, booted = false;
  const persist = () => { try { localStorage.setItem(KEY, JSON.stringify(pref)); } catch (_) { U.toast('Trình duyệt chưa cho phép lưu lựa chọn trên máy này.'); } };
  const person = () => S.get('people', pref.person);
  const mode = () => !person() ? 'staff' : pref.mode || (person().isLead ? 'lead' : 'staff');
  const isManager = () => mode() !== 'staff';
  const canEdit = () => !!person() && mode() !== 'lead';
  const mine = u => !!person() && (L.owners(u).includes(person().id) || (mode() === 'lead' && u.leadId === person().id));
  function personal() {
    const id = person() ? person().id : 'guest';
    pref.users = pref.users && typeof pref.users === 'object' ? pref.users : {};
    return pref.users[id] || (pref.users[id] = { favorites: [], recent: [], drafts: {} });
  }
  const activeLib = () => S.all('library').filter(x => x.status !== 'Deprecated');
  const agentsForTask = id => activeLib().filter(x => x.type === 'agent' && x.useCaseId === id);
  function inlineAgents(id) {
    const list = agentsForTask(id);
    return list.length ? `<div class="inline-agents"><span class="inline-ai-label">Trợ lý cho việc này</span>${list.map(x=>`<button class="inline-agent" data-resource="${esc(x.id)}">${esc(nameOf(x))} ↗</button>`).join('')}</div>` : '';
  }
  const related = x => {
    const p = person(); if (!p) return false;
    const audience = !x.audience || x.audience === 'both' || x.audience === (mode() === 'lead' ? 'lead' : 'staff');
    const uc = S.get('useCases', x.useCaseId);
    return audience && (x.builderId === p.id || x.reviewerId === p.id || x.leadId === p.id || (p.groups || []).includes(x.groupId) || (uc && mine(uc)));
  };
  const normalize = x => String(x || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/đ/g, 'd').replace(/Đ/g, 'D').toLowerCase();
  const matches = (q, ...parts) => normalize(parts.join(' ')).includes(normalize(q).trim());
  const safeURL = url => { try { const u = new URL(url); return u.protocol === 'https:' ? u.href : ''; } catch (_) { return ''; } };
  const agentNames = { 'AG-01': 'Theo dõi chỉ đạo', 'AG-02': 'Kiểm tra hồ sơ đoàn kiểm tra', 'AG-03': 'Tra cứu quy chế nội bộ', 'AG-04': 'Lập công việc cho đoàn kiểm tra', 'AG-05': 'Bản tin đầu ngày' };
  const agentKinds = { 'AG-01': 'Theo sự kiện', 'AG-02': 'Theo hồ sơ', 'AG-03': 'Hỏi khi cần', 'AG-04': 'Theo hồ sơ', 'AG-05': 'Theo lịch' };
  const nameOf = x => x.displayName || (x.type === 'agent' && agentNames[x.id]) || x.name;
  const kindOf = x => x.type === 'agent' ? (agentKinds[x.id] || 'Trợ lý công việc') : x.type === 'skill' ? 'Quy trình từng bước' : 'Mẫu câu lệnh';
  function availability(x) {
    const url = safeURL(x.launchUrl);
    if (x.status === 'Deprecated') return { label: 'Đã ngừng dùng', action: 'Xem thông tin', class: 'gray', url: '' };
    if (x.type !== 'agent') return { label: x.status === 'Approved' ? 'Nội dung đã duyệt' : x.status === 'Testing' ? 'Nội dung thử nghiệm' : 'Nội dung dự thảo', action: x.status === 'Draft' ? 'Xem bản dự thảo' : 'Dùng mẫu này', class: x.status === 'Approved' ? 'green' : 'amber', url: '' };
    if (url && x.status === 'Approved' && x.deployment === 'ready') return { label: 'Có đường dẫn sử dụng', action: 'Mở trợ lý', class: 'green', url };
    if (url && x.status !== 'Draft' && x.deployment === 'trial') return { label: 'Có bản thử nghiệm', action: 'Mở bản thử nghiệm', class: 'amber', url };
    return { label: x.status === 'Draft' ? 'Đang xây dựng' : 'Chưa kết nối trợ lý', action: 'Xem hướng dẫn thiết lập', class: 'gray', url: '' };
  }
  const icon = key => AIM.icons[key] || AIM.icons.usecases;
  const btn = (label, key, params, cls = 'btn') => `<button class="${cls}" data-route="${esc(key)}"${params ? ` data-params="${esc(JSON.stringify(params))}"` : ''}>${esc(label)}</button>`;
  const badge = (text, cls = '') => `<span class="pill ${cls}">${esc(text)}</span>`;
  const empty = (title, detail, action = '') => `<div class="empty-state"><h3>${esc(title)}</h3><p>${esc(detail)}</p>${action}</div>`;
  const section = (number, title, action = '', note = '') => `<div class="section-head"><div><h3><span class="section-number">${number}</span>${esc(title)}</h3>${note ? `<p>${esc(note)}</p>` : ''}</div>${action}</div>`;
  const pageHead = (title, description, action = '') => `<div class="page-head"><div><div class="eyebrow">${esc(C.workspace.name)} / ${esc(C.workspace.organization)}</div><h2>${esc(title)}</h2><p>${esc(description)}</p></div>${action}</div>`;
  const metric = (label, value, note, unit = '') => `<div class="metric"><div class="label">${esc(label)}</div><strong>${esc(value)}${unit ? `<em>${esc(unit)}</em>` : ''}</strong><small>${esc(note)}</small></div>`;
  const dueText = u => { const d = L.dueState(u.deadline, u.status === 'Approved'); return d ? `${d.label} · ${U.shortDate(u.deadline)}` : u.deadline ? U.date(u.deadline) : 'Chưa có thời hạn'; };
  const prioritySort = (a, b) => (a.status === 'Approved') - (b.status === 'Approved') || String(a.deadline || '9999').localeCompare(b.deadline || '9999') || ((C.priorities[b.priority] || {}).rank || 0) - ((C.priorities[a.priority] || {}).rank || 0);
  function taskRows(list, limit = Infinity) {
    if (!list.length) return empty('Chưa có công việc trong mục này', 'Thử xem công việc của Ban hoặc chọn lại cán bộ.', btn('Xem công việc của Ban', 'tasks', { scope: 'all' }, 'btn'));
    return `<div class="task-list">${[...list].sort(prioritySort).slice(0, limit).map((u, i) => `<article class="task-row"><div class="task-mark">${String(i + 1).padStart(2, '0')}</div><div><h4><button class="task-name" data-task="${esc(u.id)}">${esc(u.task)}</button></h4><p class="next">${esc(u.next || u.aiStep || 'Mở công việc để xem hướng dẫn.')}</p><div class="task-meta">${U.status(u.status)}<span>${esc(dueText(u))}</span><span>${esc(U.group(u.groupId).short)}</span></div>${inlineAgents(u.id)}</div><button class="text-btn task-action" data-task="${esc(u.id)}">Mở công việc ↗</button></article>`).join('')}</div>`;
  }
  function resourceCard(x) {
    const a = availability(x), saved = (personal().favorites || []).includes(x.id);
    return `<article class="resource-card"><div class="resource-top"><div class="resource-icon" aria-hidden="true">${icon(x.type === 'agent' ? 'agents' : x.type === 'skill' ? 'skills' : 'prompts')}</div><button class="favorite ${saved ? 'on' : ''}" data-favorite="${esc(x.id)}" aria-label="${saved ? 'Bỏ lưu' : 'Lưu'} ${esc(nameOf(x))}" aria-pressed="${saved}">${saved ? '★' : '☆'}</button></div><div class="resource-kind">${esc(kindOf(x))} · ${esc(U.group(x.groupId).short)}</div><h3 style="margin-top:7px">${esc(nameOf(x))}</h3><p class="description">${esc(x.purpose)}</p><div class="outcome"><b>Kết quả nhận được</b>${esc(x.output || 'Xem hướng dẫn chi tiết')}</div><div class="status-line">${badge(a.label, a.class)}${x.type === 'agent' ? badge(U.stLabel(x.status), 'gray') : ''}</div><div class="resource-foot"><button class="btn ${x.type === 'agent' && !a.url ? '' : 'primary'}" data-resource="${esc(x.id)}">${esc(a.action)} ↗</button><span class="resource-kind">${esc((C.audiences[x.audience] || C.audiences.both).label)}</span></div></article>`;
  }
  function resourceGrid(list, two = false) { return list.length ? `<div class="catalog-grid${two ? ' two' : ''}">${list.map(resourceCard).join('')}</div>` : empty('Chưa có nội dung phù hợp', 'Thử đổi phạm vi, từ khóa hoặc bỏ bớt bộ lọc.', '<button class="btn" data-clear-filters>Bỏ bộ lọc</button>'); }
  function saveRecent(id) { const p = personal(); p.recent = [id, ...(p.recent || []).filter(i => i !== id)].slice(0, 8); persist(); }
  function profileForm() {
    return `<div class="profile-form"><label for="choose-person">Cán bộ sử dụng<select id="choose-person"><option value="">Chọn tên trong danh sách Ban KSNB</option>${S.all('people').map(p => U.opt(p.id, `${p.name} · ${p.unit || p.title}`, pref.person)).join('')}</select></label><label for="choose-mode">Không gian làm việc<select id="choose-mode"><option value="auto">Theo chức danh cán bộ</option>${U.opt('staff', 'Chuyên viên · công việc của tôi', pref.mode)}${U.opt('lead', 'Lãnh đạo · theo dõi và rà soát', pref.mode)}${U.opt('coordinator', 'Đầu mối AI · triển khai và thư viện', pref.mode)}</select></label><button class="btn primary" data-save-profile>Vào không gian làm việc →</button></div><p class="small-note">Lựa chọn được ghi nhớ trên trình duyệt này. Bản thí điểm dùng lựa chọn cán bộ, chưa có đăng nhập hay phân quyền tài khoản.</p>`;
  }
  function selectProfile() {
    U.modal({ title: 'Không gian làm việc của bạn', body: profileForm(), foot: '<button class="btn" data-close>Đóng</button>' });
  }
  function renderHome(el) {
    const p = person();
    if (!p) {
      el.innerHTML = `<div class="hero"><div class="eyebrow">PVEP / Giai đoạn 01 · Ban KSNB</div><h2>Đúng công việc.<br>Đúng trợ lý. Dễ bắt đầu.</h2><p>Tìm mẫu AI phù hợp với nhiệm vụ và từng bước đưa Copilot vào công việc hằng ngày của Ban.</p></div><div class="onboard"><div class="surface"><h2>Bắt đầu từ công việc của bạn</h2><p>Chọn tên để xem phân công, mẫu gợi ý và nội dung cần tiếp tục.</p>${profileForm()}</div><div class="btn-row" style="justify-content:center;margin-top:20px">${btn('Khám phá kho mẫu trước', 'catalog', { scope: 'all' }, 'text-btn')}${btn('Xem hướng dẫn bắt đầu', 'guide', null, 'text-btn')}</div></div>`; return;
    }
    const tasks = S.all('useCases').filter(mine), outstanding = tasks.filter(u => u.status !== 'Approved');
    const build = activeLib().filter(x => x.builderId === p.id && x.status !== 'Approved');
    const reviews = activeLib().filter(x => x.reviewerId === p.id && x.status === 'Testing');
    const suggested = activeLib().filter(x => x.type !== 'agent' && x.status === 'Approved' && related(x)).slice(0, 3);
    const recents = (personal().recent || []).map(id => S.get('library', id)).filter(x => x && x.status !== 'Deprecated').slice(0, 3);
    const title = mode() === 'lead' ? 'Nắm việc cần xem xét.\nTheo sát hiệu quả triển khai.' : mode() === 'coordinator' ? 'Từ thử nghiệm nhỏ,\nđến ứng dụng thiết thực.' : 'Một ngày làm việc rõ ràng hơn.';
    el.innerHTML = `<div class="hero"><div class="eyebrow">Không gian của ${esc(p.name)}</div><h2>${esc(title).replace(/\n/g, '<br>')}</h2><p>${mode() === 'lead' ? 'Theo dõi công việc phụ trách, rà soát nội dung AI và xem tiến độ của Ban.' : mode() === 'coordinator' ? 'Hoàn thiện thư viện, kết nối trợ lý và hỗ trợ cán bộ sử dụng đúng nhiệm vụ.' : `${esc(p.unit || p.title)} · Mẫu AI và hướng dẫn được gợi ý từ nhóm công việc và phân công của bạn.`}</p><div class="btn-row">${btn(mode() === 'lead' ? 'Xem điều hành' : 'Mở công việc của tôi', mode() === 'lead' ? 'dashboard' : 'tasks', null, 'btn primary')}${btn('Tìm mẫu phù hợp', 'catalog', { scope: 'mine' }, 'btn ghost')}</div><div class="hero-index">PVEP / KSNB · 01</div></div><div class="metrics">${metric('Công việc được phân công', tasks.length, mode() === 'lead' ? 'Theo lãnh đạo phụ trách' : 'Theo người thực hiện')}${metric('Ứng dụng đang triển khai', outstanding.length, 'Trạng thái dự thảo hoặc thử nghiệm')}${metric('Nội dung cần rà soát', reviews.length, 'Đang thử nghiệm, bạn là người rà soát')}${metric('Mẫu AI đang xây dựng', build.length, 'Bạn là người xây dựng')}</div><div class="workspace-grid"><div class="surface">${section('01', 'Công việc cần tiếp tục', btn('Xem tất cả →', 'tasks', null, 'text-btn'))}${taskRows(outstanding.length ? outstanding : tasks, 4)}</div><aside class="workspace-aside"><div class="surface">${section('02', 'Bắt đầu nhanh')}<div class="quick-list">${quick('Rà soát tờ trình', 'Tìm căn cứ, thẩm quyền và điểm cần làm rõ', 'catalog', { q: 'tờ trình', scope: 'all' })}${quick('Soạn Phiếu ý kiến', 'Dùng khung nội dung của Ban KSNB', 'catalog', { q: 'phiếu ý kiến', scope: 'all' })}${quick('Tổng hợp báo cáo', 'Từ ghi chú công việc đến báo cáo có cấu trúc', 'catalog', { q: 'báo cáo', scope: 'all' })}</div></div><div class="aside-note"><div class="eyebrow">Trợ lý theo nhiệm vụ</div><h3>Có việc cần theo dõi thường xuyên?</h3><p>Khám phá các trợ lý hồ sơ, chỉ đạo và quy chế. Mỗi trợ lý ghi rõ phạm vi và tình trạng kết nối.</p>${btn('Khám phá trợ lý →', 'agents', null, 'text-btn')}</div></aside></div>${recents.length ? `<div class="block-space">${section('03', 'Bạn vừa mở', btn('Mẫu đã lưu →', 'catalog', { scope: 'saved' }, 'text-btn'))}${resourceGrid(recents)}</div>` : ''}<div class="block-space">${section(recents.length ? '04' : '03', 'Mẫu phù hợp với công việc', btn('Mở kho mẫu →', 'catalog', { scope: 'mine' }, 'text-btn'), 'Ưu tiên nội dung đã duyệt, cùng nhóm công việc hoặc có liên quan đến phân công.')} ${suggested.length ? resourceGrid(suggested) : empty('Chưa có mẫu đã duyệt phù hợp với phân công', 'Bạn vẫn có thể tìm trong toàn bộ kho mẫu của Ban.', btn('Khám phá kho mẫu', 'catalog', { scope: 'all' }))}</div>`;
  }
  function quick(title, note, route, params) { return `<button class="quick-link" data-route="${esc(route)}" data-params="${esc(JSON.stringify(params || {}))}"><span><b>${esc(title)}</b><small>${esc(note)}</small></span><span class="arrow">↗</span></button>`; }
  function renderTasks(el, params = {}) {
    let f = { scope: params.scope || (person() ? 'mine' : 'all'), q: params.q || '', group: params.group || '', status: params.status || '', owner: params.owner || '', tool: params.tool || '', due: params.due || '' };
    el.innerHTML = pageHead('Công việc & phân công', 'Chọn một nhiệm vụ để thấy bước tiếp theo, mẫu AI và trợ lý liên quan.', canEdit() ? '<button class="btn primary" data-add-task>+ Thêm công việc</button>' : '') + `<div class="tabs" id="taskScopes">${[['mine', 'Việc của tôi'], ['all', 'Công việc của Ban'], ['build', 'Mẫu tôi xây dựng'], ['review', 'Nội dung tôi rà soát']].map(([k, v]) => `<button data-task-scope="${k}" class="${f.scope === k ? 'active' : ''}">${v}</button>`).join('')}<span class="tab-spacer"></span>${isManager() ? btn('Bảng quản lý đầy đủ ↗', 'register', params, 'text-btn') : ''}</div><div class="searchbar"><div class="searchbox"><label class="sr-only" for="taskSearch">Tìm công việc</label><input id="taskSearch" type="search" placeholder="Tìm công việc, người thực hiện, bước tiếp theo…" value="${esc(f.q)}"></div><label class="sr-only" for="taskStatus">Trạng thái</label><select class="filter-select" id="taskStatus">${U.opt('', 'Mọi trạng thái', f.status)}${C.useCaseStatuses.map(s => U.opt(s, U.stLabel(s), f.status)).join('')}</select></div><details class="filters"><summary>Lọc theo nhóm, người thực hiện và thời hạn</summary><div class="filter-grid"><label>Nhóm công việc<select class="filter-select" data-tfilter="group">${U.opt('', 'Mọi nhóm', f.group)}${U.groupOpts().map(([v, l]) => U.opt(v, l, f.group)).join('')}</select></label><label>Người thực hiện<select class="filter-select" data-tfilter="owner">${U.opt('', 'Mọi cán bộ', f.owner)}${U.peopleOpts().map(([v, l]) => U.opt(v, l, f.owner)).join('')}</select></label><label>Thời hạn triển khai<select class="filter-select" data-tfilter="due">${U.opt('', 'Tất cả', f.due)}${U.opt('soon', 'Sắp đến hạn', f.due)}${U.opt('over', 'Quá hạn', f.due)}</select></label></div></details><div id="taskResults"></div>`;
    function draw() {
      let list;
      if (['build', 'review'].includes(f.scope)) {
        list = activeLib().filter(x => person() && x[f.scope === 'build' ? 'builderId' : 'reviewerId'] === person().id && (!f.status || x.status === f.status) && (!f.group || x.groupId === f.group) && (!f.owner || x.builderId === f.owner) && (!f.due || L.dueState(x.deadline, x.status === 'Approved')?.key === f.due) && matches(f.q, x.name, x.purpose));
        U.$('#taskResults', el).innerHTML = `<div class="result-meta">${list.length} nội dung · trạng thái thể hiện tiến độ xây dựng và rà soát</div>` + resourceGrid(list); return;
      }
      list = S.all('useCases').filter(u => (f.scope === 'all' || mine(u)) && (!f.group || u.groupId === f.group) && (!f.status || u.status === f.status) && (!f.owner || L.owners(u).includes(f.owner)) && (!f.tool || u.tool === f.tool) && (!f.due || L.dueState(u.deadline, u.status === 'Approved')?.key === f.due) && matches(f.q, u.task, u.next, u.pain, ...L.owners(u).map(U.pname)));
      U.$('#taskResults', el).innerHTML = `<div class="result-meta">${list.length} công việc · phạm vi ${f.scope === 'mine' ? 'cán bộ đã chọn' : esc(C.workspace.name)} · trạng thái là tiến độ ứng dụng AI</div>` + (list.length ? `<div class="surface">${taskRows(list)}</div>` : empty('Chưa có công việc phù hợp', !person() && f.scope === 'mine' ? 'Chọn cán bộ để xem phân công của mình.' : 'Thử đổi bộ lọc hoặc xem công việc của Ban.', '<button class="btn" data-reset-tasks>Bỏ lọc và xem công việc của Ban</button>'));
    }
    el.addEventListener('input', e => { if (e.target.id === 'taskSearch') { f.q = e.target.value; draw(); } });
    el.addEventListener('change', e => { if (e.target.id === 'taskStatus') f.status = e.target.value; if (e.target.dataset.tfilter) f[e.target.dataset.tfilter] = e.target.value; draw(); });
    el.addEventListener('click', e => { const t = e.target.closest('[data-task-scope]'); if (t) { f.scope = t.dataset.taskScope; U.$$('#taskScopes button[data-task-scope]', el).forEach(b => b.classList.toggle('active', b === t)); draw(); } if(e.target.closest('[data-reset-tasks]')) go('tasks', {scope:'all'}); }); draw();
  }
  function renderCatalog(el, params = {}, agentsOnly = false) {
    let f = { q: params.q || '', scope: params.scope || (person() ? 'mine' : 'all'), type: agentsOnly ? 'agent' : params.type || '', group: params.group || '', domain: params.domain || '', status: params.status || '', audience: '', builder: '' };
    const title = agentsOnly ? 'Trợ lý theo công việc' : 'Kho mẫu AI';
    el.innerHTML = pageHead(title, agentsOnly ? 'Biết trợ lý giúp việc gì, cần dữ liệu nào và đã có thể sử dụng ở đâu.' : 'Tìm bằng tên công việc. Mỗi mẫu có đầu vào, đầu ra và hướng dẫn sử dụng.', canEdit() ? `<button class="btn" data-add-resource="${agentsOnly ? 'agent' : 'prompt'}">+ ${agentsOnly ? 'Thêm trợ lý' : 'Thêm mẫu'}</button>` : '') + `<div class="searchbar"><div class="searchbox"><label class="sr-only" for="catalogSearch">${agentsOnly ? 'Tìm trợ lý' : 'Tìm mẫu theo công việc'}</label><input id="catalogSearch" type="search" value="${esc(f.q)}" placeholder="${agentsOnly ? 'Bạn cần theo dõi chỉ đạo, kiểm tra hồ sơ hay tra cứu quy chế?' : 'Bạn cần rà soát tờ trình, soạn phiếu ý kiến hay tổng hợp báo cáo?'}"></div></div><div class="tabs" id="catalogScopes">${[['mine', 'Dành cho tôi'], ['all', 'Tất cả'], ['saved', 'Đã lưu'], ['domain', 'Theo lĩnh vực']].map(([k, v]) => `<button data-scope="${k}" class="${f.scope === k ? 'active' : ''}">${v}</button>`).join('')}<span class="tab-spacer"></span>${agentsOnly ? (isManager() ? btn('Sơ đồ hệ thống ↗', 'agentmap', null, 'text-btn') : '') : `<label class="sr-only" for="catalogType">Loại nội dung</label><select id="catalogType" class="filter-select">${U.opt('', 'Mẫu & quy trình', f.type)}${U.opt('prompt', 'Mẫu câu lệnh', f.type)}${U.opt('skill', 'Quy trình từng bước', f.type)}</select>`}</div><details class="filters" id="catalogFilters" ${f.scope === 'domain' ? 'open' : ''}><summary>Bộ lọc chi tiết · nhóm công việc, lĩnh vực, trạng thái</summary><div class="filter-grid"><label>Nhóm công việc<select class="filter-select" data-filter="group">${U.opt('', 'Mọi nhóm trong Ban', f.group)}${U.groupOpts().map(([v,l])=>U.opt(v,l,f.group)).join('')}</select></label><label>Lĩnh vực chuyên môn<select class="filter-select" data-filter="domain">${U.opt('', 'Mọi lĩnh vực', f.domain)}${U.domainOpts().map(([v,l])=>U.opt(v,l,f.domain)).join('')}</select></label><label>Trạng thái nội dung<select class="filter-select" data-filter="status">${U.opt('', 'Nội dung đang duy trì', f.status)}${C.libraryStatuses.map(s=>U.opt(s,U.stLabel(s),f.status)).join('')}</select></label><label>Đối tượng dùng<select class="filter-select" data-filter="audience">${U.opt('', 'Mọi đối tượng', '')}${Object.entries(C.audiences).map(([k,v])=>U.opt(k,v.label,'')).join('')}</select></label><label>Người xây dựng<select class="filter-select" data-filter="builder">${U.opt('', 'Mọi cán bộ', '')}${U.peopleOpts().map(([v,l])=>U.opt(v,l,'')).join('')}</select></label></div></details><div id="catalogResults"></div>${agentsOnly ? '<div class="callout"><div><strong>Trợ lý đang được phát triển tại Ban KSNB.</strong><br>“Đã duyệt” là trạng thái nội dung. Chỉ hiển thị nút mở trợ lý khi đã cấu hình đường dẫn và tình trạng triển khai. Tiêu chí tự động hóa được xem riêng trong thông tin quản lý.</div></div>' : ''}`;
    function draw() {
      let list = S.all('library').filter(x => (agentsOnly ? x.type === 'agent' : x.type !== 'agent') && (!f.type || x.type === f.type) && (f.status ? x.status === f.status : x.status !== 'Deprecated') && (f.scope !== 'mine' || related(x)) && (f.scope !== 'saved' || (personal().favorites || []).includes(x.id)) && (!f.group || x.groupId === f.group) && (!f.domain || x.domainId === f.domain) && (!f.audience || x.audience === f.audience || x.audience === 'both') && (!f.builder || x.builderId === f.builder) && matches(f.q, nameOf(x), x.name, x.purpose, x.output, x.id, U.group(x.groupId).name, U.domain(x.domainId).name, (S.get('useCases',x.useCaseId)||{}).task));
      list.sort((a,b) => (b.status === 'Approved') - (a.status === 'Approved') || nameOf(a).localeCompare(nameOf(b),'vi'));
      let html = `<div class="result-meta" aria-live="polite">${list.length} ${agentsOnly ? 'trợ lý' : 'mẫu / quy trình'} · ${f.status === 'Deprecated' ? 'nội dung đã ngừng dùng' : 'không tính mục ngừng dùng khi chưa chọn trạng thái'} · nguồn nội dung: Ban KSNB</div>`;
      if (f.scope === 'domain' && list.length) html += C.domains.map(d => { const rows = list.filter(x=>x.domainId===d.id); return rows.length ? `<div class="block-space">${section('', d.name, '', `${rows.length} nội dung do Ban KSNB xây dựng`)}${resourceGrid(rows)}</div>` : ''; }).join('') + (list.some(x=>!C.domains.some(d=>d.id===x.domainId)) ? `<div class="block-space">${section('','Chưa phân loại lĩnh vực')}${resourceGrid(list.filter(x=>!C.domains.some(d=>d.id===x.domainId)))}</div>` : '');
      else html += resourceGrid(list);
      U.$('#catalogResults', el).innerHTML = html;
    }
    el.addEventListener('input', e => { if(e.target.id === 'catalogSearch') { f.q=e.target.value;draw(); } });
    el.addEventListener('change', e => { if(e.target.id === 'catalogType')f.type=e.target.value; if(e.target.dataset.filter)f[e.target.dataset.filter]=e.target.value;draw(); });
    el.addEventListener('click', e => {const b=e.target.closest('[data-scope]');if(b){f.scope=b.dataset.scope;U.$$('#catalogScopes [data-scope]',el).forEach(x=>x.classList.toggle('active',x===b));if(f.scope==='domain')U.$('#catalogFilters',el).open=true;draw();}if(e.target.closest('[data-clear-filters]'))go(agentsOnly?'agents':'catalog',{scope:'all'});});draw();
  }

  const agentExamples = {
    'AG-01': { title: 'Sổ theo dõi chỉ đạo', columns: ['Chỉ đạo nguồn', 'Đơn vị thực hiện', 'Thời hạn', 'Tình trạng'], cells: ['Văn bản đã chọn', 'Trích từ văn bản', 'Theo văn bản', 'Chưa có báo cáo'], steps: ['Chọn văn bản chỉ đạo và văn bản giao việc có liên quan.', 'Đối chiếu nhiệm vụ, đơn vị thực hiện và thời hạn với văn bản nguồn.', 'Kiểm tra báo cáo đơn vị trước khi cập nhật tình trạng hoàn thành.'] },
    'AG-02': { title: 'Bảng đối chiếu hồ sơ', columns: ['Mục checklist', 'Hồ sơ đối chiếu', 'Tình trạng', 'Cần xác nhận'], cells: ['Nội dung kiểm tra', 'Tệp / trang nguồn', 'Chưa thấy trong hồ sơ', 'Đề nghị đầu mối kiểm tra'], steps: ['Chọn checklist và thư mục hồ sơ đúng đợt kiểm tra.', 'Đối chiếu từng mục với tệp đã cung cấp.', 'Xác nhận danh sách cần bổ sung; “chưa thấy” không phải kết luận thiếu sót.'] },
    'AG-03': { title: 'Câu trả lời có nguồn', question: 'Thẩm quyền phê duyệt nội dung này được quy định ở đâu?', steps: ['Nêu nội dung cụ thể cần tra cứu.', 'Đọc câu trả lời cùng số hiệu văn bản, điều và khoản.', 'Mở văn bản nguồn, kiểm tra phạm vi áp dụng và danh mục hiệu lực.'] },
    'AG-04': { title: 'Bảng công việc dự thảo', columns: ['Công việc', 'Người phụ trách', 'Thời hạn', 'Nguồn'], cells: ['Trích từ hồ sơ đoàn', 'Theo phân công', 'Chưa có thời hạn nếu chưa nêu', 'Quyết định / biên bản'], steps: ['Chọn quyết định, đề cương và biên bản của đoàn.', 'Kiểm tra đầu việc, người phụ trách và thời hạn đã trích.', 'Xác nhận bảng dự thảo trước khi chuyển sang Planner đã kết nối.'] },
    'AG-05': { title: 'Bản tin đầu ngày', sections: ['Việc đến hạn và quá hạn', 'Lịch họp và tài liệu', 'Thư cần xem xét', 'Hồ sơ chờ ý kiến'], steps: ['Xác định hộp thư, lịch và sổ chỉ đạo được sử dụng.', 'Mở bản tin của ngày cần xem.', 'Mở liên kết nguồn của từng nội dung trước khi xử lý.'] }
  };
  function examplePreview(x) {
    const e = agentExamples[x.id];
    if(!e)return `<div class="demo-preview"><div class="sample-caption">Cấu trúc đầu ra dự kiến · chưa phải kết quả xử lý</div><p>${esc(x.output)}</p></div>`;
    return `<div class="demo-preview"><div class="sample-caption">Minh họa cấu trúc đầu ra · chưa xử lý dữ liệu hay kết nối hệ thống</div><h4>${e.title}</h4>${e.columns ? `<table><thead><tr>${e.columns.map(c=>`<th>${c}</th>`).join('')}</tr></thead><tbody><tr>${e.cells.map(c=>`<td>${c}</td>`).join('')}</tr></tbody></table>` : e.question ? `<p><b>Câu hỏi mẫu:</b> ${e.question}</p><p><b>Nội dung trả lời:</b> Trích quy định phù hợp từ thư viện được chỉ định.</p><p><b>Nguồn:</b> Tên văn bản · Số hiệu · Điều, khoản · Liên kết tài liệu.</p><p>Nếu không có căn cứ: “Chưa tìm thấy trong thư viện”.</p>` : `<ol>${e.sections.map(s=>`<li>${s} — kèm liên kết nguồn</li>`).join('')}</ol>`}</div>`;
  }
  function renderResource(el, params) {
    const x = S.get('library', params.id);
    if(!x){el.innerHTML=empty('Không tìm thấy nội dung', 'Nội dung có thể đã bị xóa hoặc đường dẫn không còn đúng.',btn('Mở kho mẫu','catalog'));return;}
    saveRecent(x.id);
    const uc = S.get('useCases',x.useCaseId), a = availability(x), draft = (personal().drafts || {})[x.id] || {}, agent = x.type === 'agent';
    const example = agentExamples[x.id];
    const steps = agent ? example?.steps || ['Xem phạm vi dữ liệu và cách kích hoạt.', 'Thiết lập trợ lý trên công cụ được đơn vị lựa chọn.', 'Thử nghiệm và đối chiếu kết quả với dữ liệu nguồn.'] : x.type === 'skill' && x.steps?.length ? x.steps : ['Chuẩn bị tài liệu theo yêu cầu của mẫu.', 'Sao chép hướng dẫn và mở công cụ Copilot phù hợp.', 'Cung cấp tài liệu tại công cụ được phép sử dụng và thực hiện yêu cầu.', 'Đối chiếu kết quả với nguồn, chỉnh sửa trước khi sử dụng.'];
    const checks = ['Đã xác định đúng phạm vi công việc và chuẩn bị tài liệu.', 'Đã xác định công cụ được phép dùng cho tài liệu này.', 'Sẽ đối chiếu số liệu, trích dẫn và kết quả trước khi sử dụng.'];
    el.innerHTML = `${btn('← '+(agent?'Trợ lý theo công việc':'Kho mẫu AI'),agent?'agents':'catalog',{scope:'all'},'text-btn')}${pageHead(nameOf(x),x.purpose)}<div class="status-line">${badge(a.label,a.class)}${badge(kindOf(x))}${U.status(x.status)}${U.aud(x.audience)}</div><ol class="guide-steps"><li><b>1</b> Chuẩn bị</li><li>→</li><li><b>2</b> Thực hiện</li><li>→</li><li><b>3</b> Xem kết quả</li><li>→</li><li><b>4</b> Kiểm tra</li></ol><div class="guide-grid"><div class="surface"><section class="guide-section"><div class="guide-label">01 / Chuẩn bị</div><h3>${agent?'Nguồn dữ liệu trợ lý cần':'Tài liệu cần có'}</h3><p>${esc(x.input || x.dataScope || 'Liên hệ người xây dựng để xác định dữ liệu đầu vào.')}</p>${agent && x.dataScope ? `<p><b>Phạm vi:</b> ${esc(x.dataScope)}</p>`:''}${checks.map((c,i)=>`<label class="prep-check"><input type="checkbox" data-check="${i}" ${draft.checks?.includes(i)?'checked':''}>${c}</label>`).join('')}</section><section class="guide-section"><div class="guide-label">02 / Thực hiện</div><h3>${agent?'Cách sử dụng theo nhiệm vụ':'Các bước sử dụng'}</h3><ol>${steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol>${agent ? `<div class="callout"><div><strong>${a.url?'Mở trong hệ thống đã cấu hình':'Chưa có trợ lý được kết nối trong app này'}</strong><br>${a.url?'Kết quả được xử lý tại công cụ đích. Đăng nhập bằng tài khoản có quyền sử dụng nguồn dữ liệu tương ứng.':'Nội dung dưới đây là hướng dẫn để đầu mối xây dựng hoặc thử nghiệm. App chưa tự đọc hồ sơ, gửi bản tin hay cập nhật Planner.'}</div></div>${a.url?`<a class="btn primary" href="${esc(a.url)}" target="_blank" rel="noopener noreferrer">${a.action} ↗</a>`:canEdit()?`<button class="btn" data-deployment="${esc(x.id)}">Cấu hình nơi sử dụng</button>`:''}` : `<div class="callout"><div><strong>Công cụ: ${esc((C.tools[uc?.tool]||{}).label||'Theo hướng dẫn của người xây dựng')}</strong><br>App cung cấp mẫu và hướng dẫn. Việc xử lý tài liệu diễn ra trong Copilot/công cụ của bạn.</div></div>`}<details ${agent?'':'open'} class="management-details"><summary>${agent?'Hướng dẫn xây dựng / thiết lập trợ lý':'Nội dung mẫu câu lệnh'}</summary><pre class="readable-prompt">${esc(x.instruction || 'Chưa có hướng dẫn.')}</pre><button class="btn ${agent?'':'primary'}" data-copy-instruction="${esc(x.id)}" ${x.status==='Deprecated'?'disabled':''}>${agent?'Sao chép hướng dẫn thiết lập':'Sao chép mẫu câu lệnh'}</button>${x.status!=='Approved'?'<p class="small-note">Nội dung chưa được duyệt chính thức; dùng trong phạm vi thử nghiệm và cần rà soát.</p>':''}</details></section><section class="guide-section"><div class="guide-label">03 / Kết quả</div><h3>Kết quả cần nhận được</h3><p>${esc(x.output)}</p>${agent?examplePreview(x):''}</section><section class="guide-section"><div class="guide-label">04 / Kiểm tra</div><h3>Trước khi sử dụng kết quả</h3><p>${esc(x.guardrails || 'Đối chiếu số liệu và trích dẫn với tài liệu nguồn; kiểm tra phạm vi, thể thức và người có trách nhiệm rà soát. Không dùng nội dung chưa có căn cứ.')}</p></section><section class="guide-section"><label for="resourceNote"><h3>Ghi chú để tiếp tục lần sau</h3></label><textarea class="notes-input" id="resourceNote" maxlength="5000" placeholder="Ghi bước đang làm, điều cần xác minh hoặc kết quả cần kiểm tra…">${esc(draft.note||'')}</textarea><div class="btn-row" style="margin-top:10px"><button class="btn" data-save-draft="${esc(x.id)}">Lưu ghi chú & bước chuẩn bị</button><span class="small-note" id="draftStatus" role="status">Lưu riêng theo cán bộ trên trình duyệt này.</span></div></section></div><aside><div class="surface"><div class="guide-label">Thông tin sử dụng</div><dl class="detail-meta"><div><dt>Dành cho</dt><dd>${esc((C.audiences[x.audience]||C.audiences.both).label)}</dd></div><div><dt>Nhóm công việc</dt><dd>${esc(U.group(x.groupId).name)}</dd></div>${agent?`<div><dt>Khi nào sử dụng</dt><dd>${esc(x.trigger||'Theo nhu cầu công việc')}</dd></div>`:''}<div><dt>Người xây dựng / hỗ trợ nội dung</dt><dd>${esc(U.pname(x.builderId))}</dd></div><div><dt>Người rà soát</dt><dd>${esc(U.pname(x.reviewerId))}</dd></div><div><dt>Lĩnh vực chuyên môn</dt><dd>${esc(U.domain(x.domainId).name)}</dd></div></dl><div class="btn-row" style="margin-top:19px"><button class="btn" data-favorite="${esc(x.id)}" aria-pressed="${(personal().favorites||[]).includes(x.id)}">${(personal().favorites||[]).includes(x.id)?'★ Đã lưu':'☆ Lưu để dùng lại'}</button></div></div>${uc?`<div class="aside-note"><h3>Công việc liên quan</h3><p>${esc(uc.task)}</p><button class="text-btn" data-task="${esc(uc.id)}">Mở nhiệm vụ →</button></div>`:''}<details class="surface management-details"><summary>Thông tin quản lý & phát triển</summary><dl class="detail-meta"><div><dt>Mã / phiên bản</dt><dd>${esc(x.id)} · ${esc(x.version||'Chưa ghi')}</dd></div><div><dt>Cập nhật</dt><dd>${U.date(x.updated)}</dd></div><div><dt>Thời hạn xây dựng</dt><dd>${U.date(x.deadline)}</dd></div><div><dt>Lãnh đạo phụ trách</dt><dd>${esc(U.pname(x.leadId))}</dd></div><div><dt>Trạng thái nội dung</dt><dd>${U.status(x.status)}</dd></div>${uc?`<div><dt>Tiết kiệm ước tính của công việc liên quan</dt><dd>${nf(L.savedHours(uc),1)} giờ/tháng<p class="small-note">Chưa phải số liệu đo lường riêng của mẫu / trợ lý.</p></dd></div>`:''}</dl>${agent&&uc?`<div class="block-space"><p class="small-note">${C.agentCriteria.filter(c=>L.criteria(uc)[c.key]).length}/5 tiêu chí để xem xét tự động hóa. Không xác nhận trợ lý đã vận hành.</p>${legacy.usecases.critList(uc)}</div>`:''}${canEdit()?`<div class="btn-row" style="margin-top:18px"><button class="btn" data-edit-resource="${esc(x.id)}">Sửa nội dung</button>${agent?`<button class="btn" data-deployment="${esc(x.id)}">Nơi sử dụng</button>`:''}<button class="btn danger" data-delete-resource="${esc(x.id)}">Xóa nội dung</button></div>`:''}</details></aside></div>`;
  }
  function renderTask(el, params) {
    const u=S.get('useCases',params.id);
    if(!u){el.innerHTML=empty('Không tìm thấy công việc','Kiểm tra lại đường dẫn hoặc mở danh sách công việc.',btn('Mở công việc','tasks'));return;}
    const items=L.libFor(u.id).filter(x=>x.status!=='Deprecated');
    el.innerHTML = `${btn('← Công việc & phân công','tasks',null,'text-btn')}${pageHead(u.task,u.aiStep||u.pain,canEdit()?`<button class="btn" data-edit-task="${esc(u.id)}">Cập nhật công việc</button>`:'')}<div class="guide-grid"><div><div class="surface"><div class="status-line">${U.status(u.status)}${U.prio(u.priority)}${badge(dueText(u))}</div><section class="guide-section"><div class="guide-label">Bước tiếp theo</div><h3>${esc(u.next||'Trao đổi với người phụ trách để xác định bước tiếp theo.')}</h3></section><div class="guide-section"><h3>AI hỗ trợ ở đâu?</h3><p>${esc(u.aiStep)}</p></div><div class="guide-section"><h3>Cách làm hiện tại & vướng mắc</h3><p>${esc(u.current)}</p><p>${esc(u.pain)}</p></div><div class="callout"><div><strong>Lộ trình sử dụng</strong><br>Chuẩn bị hồ sơ → Chọn mẫu liên quan → Thực hiện ở công cụ phù hợp → Kiểm tra kết quả.</div></div></div><div class="block-space">${section('01','Mẫu & trợ lý cho công việc này','', 'Ưu tiên nội dung đã duyệt; mở từng mục để xem đầu vào và cách dùng.')}${items.length?resourceGrid([...items].sort((a,b)=>(b.status==='Approved')-(a.status==='Approved')),true):empty('Chưa có mẫu gắn với công việc này','Tìm trong kho mẫu hoặc trao đổi với đầu mối để xây dựng hướng dẫn.',btn('Tìm trong kho mẫu','catalog',{scope:'all',group:u.groupId}))}</div></div><aside><div class="surface"><div class="guide-label">Phân công</div><dl class="detail-meta"><div><dt>Người thực hiện</dt><dd>${L.owners(u).map(id=>esc(U.pname(id))).join('<br>')||'Chưa phân công'}</dd></div><div><dt>Lãnh đạo phụ trách</dt><dd>${esc(U.pname(u.leadId))}</dd></div><div><dt>Nhóm công việc</dt><dd>${esc(U.group(u.groupId).name)}</dd></div><div><dt>Công cụ</dt><dd>${esc(C.tools[u.tool]?.label||'Chưa xác định')}</dd></div><div><dt>Thời hạn triển khai</dt><dd>${U.date(u.deadline)}</dd></div></dl></div><div class="aside-note"><h3>Hiệu quả ước tính</h3><p>${nf(u.before,1)} → ${nf(u.after,1)} giờ/lần</p><p><strong>${nf(L.savedHours(u),1)} giờ/tháng</strong> theo ${nf(u.perMonth,2)} lần/tháng.</p><p class="small-note">Tính từ thời gian và tần suất đã khai báo, chưa phải số liệu đo lường.</p></div><details class="surface management-details"><summary>Chi tiết đánh giá tự động hóa</summary><p class="small-note">Tiêu chí phục vụ lựa chọn mức phát triển phù hợp.</p>${legacy.usecases.critList(u)}<button class="text-btn" data-technical-task="${esc(u.id)}">Mở hồ sơ quản lý đầy đủ →</button></details></aside></div>`;
  }
  function renderDashboard(el) {
    const sm=L.summary(), ppl=S.all('people'), surveyed=ppl.filter(p=>p.usage&&p.usage!=='unknown'), using=surveyed.filter(p=>['daily','weekly','occasional'].includes(p.usage)), ucs=S.all('useCases');
    const overdue=ucs.filter(u=>L.dueState(u.deadline,u.status==='Approved')?.key==='over'), soon=ucs.filter(u=>L.dueState(u.deadline,u.status==='Approved')?.key==='soon');
    const top=[...ucs].filter(u=>u.status==='Approved').sort((a,b)=>L.savedHours(b)-L.savedHours(a)).slice(0,4);
    const plan=S.all('milestones');
    el.innerHTML=pageHead('Điều hành triển khai AI','Theo dõi việc cần xử lý, tiến độ và hiệu quả ước tính trong phạm vi Ban KSNB.',btn('Xem lộ trình →','roadmap',null,'btn'))+`<div class="metrics">${metric('Nhiệm vụ triển khai quá hạn',overdue.length,'Không tính ứng dụng đã duyệt')}${metric('Nhiệm vụ sắp đến hạn',soon.length,`Trong ${C.thresholds.dueSoonDays} ngày tới`)}${metric('Ứng dụng AI đã duyệt',sm.byStatus.Approved,`Trên ${sm.useCases} ứng dụng của Ban`)}${metric('Tiết kiệm ước tính',nf(sm.savedApproved),'Chỉ tính ứng dụng đã duyệt','giờ/tháng')}</div><div class="workspace-grid"><section class="surface">${section('01','Việc cần quan tâm',btn('Mở danh sách →','tasks',{scope:'all',due:overdue.length?'over':'soon'},'text-btn'), 'Ưu tiên quá hạn và sắp đến hạn triển khai.')}${overdue.length||soon.length?taskRows([...overdue,...soon],4):empty('Chưa có nhiệm vụ quá hạn hoặc sắp đến hạn','Xem danh sách công việc để theo dõi các mốc tiếp theo.',btn('Xem công việc','tasks',{scope:'all'}))}</section><section class="surface">${section('02','Mức độ tham gia')}<div class="progress-label">Cán bộ có phân công ứng dụng AI</div><div style="font-size:31px;font-weight:600">${sm.withUseCase}<span style="font-size:15px;color:var(--muted)"> / ${sm.people}</span></div>${U.bar(sm.withUseCase/(sm.people||1)*100)}<p class="chart-note">Có phân công không đồng nghĩa đã sử dụng thường xuyên.</p><div class="block-space"><div class="progress-label">Mức độ sử dụng Copilot</div><p style="font-size:14px;font-weight:600">${surveyed.length?`${using.length}/${surveyed.length} người đã khảo sát có sử dụng`:'Chưa có dữ liệu khảo sát'}</p><p class="chart-note">${ppl.length-surveyed.length}/${ppl.length} cán bộ chưa khảo sát. Không quy đổi thành “chưa sử dụng”.</p>${btn('Xem cán bộ →','people',null,'text-btn')}</div></section></div><div class="chart-grid"><section class="surface">${section('03','Thực tế so với kế hoạch','', 'Theo các đầu việc hoàn thành của từng mốc.')} ${plan.map(m=>{const act=L.milestoneProgress(m),planned=L.milestonePlanned(m),st=L.milestoneState(m);return `<div class="chart-row"><div class="chart-row-head"><button data-route="roadmap">${esc(m.name)}</button><span>${pct(act)}</span></div><div class="bar-pair"><span>Thực tế</span><div class="chart-track"><div class="chart-fill" style="width:${Math.min(100,act)}%"></div></div><span>${pct(act)}</span></div><div class="bar-pair"><span>Kế hoạch</span><div class="chart-track"><div class="chart-fill plan" style="width:${Math.min(100,planned)}%"></div></div><span>${pct(planned)}</span></div><p class="chart-note">${esc(st.label)} · Hạn ${U.date(m.end)}</p></div>`;}).join('')}</section><section class="surface">${section('04','Hiệu quả trước & sau AI','', 'Ứng dụng đã duyệt · giờ mỗi lần thực hiện.')} ${top.length?top.map(u=>`<div class="chart-row"><div class="chart-row-head"><button data-task="${esc(u.id)}">${esc(u.task)}</button></div><div class="bar-pair"><span>Trước</span><div class="chart-track"><div class="chart-fill before" style="width:100%"></div></div><span>${nf(u.before,1)} giờ</span></div><div class="bar-pair"><span>Sau</span><div class="chart-track"><div class="chart-fill" style="width:${Math.max(0,Math.min(100,u.after/(u.before||1)*100))}%"></div></div><span>${nf(u.after,1)} giờ</span></div><p class="chart-note">Ước tính tiết kiệm ${nf(L.savedHours(u),1)} giờ/tháng · ${nf(u.perMonth,2)} lần/tháng</p></div>`).join(''):empty('Chưa có ứng dụng đã duyệt','Chỉ hiển thị so sánh khi có dữ liệu phù hợp.')}<p class="chart-note">Độ dài thanh được chuẩn hóa riêng theo từng công việc. Số giờ là giá trị khai báo; cần đo lường khi vận hành.</p></section></div><details class="surface management-details"><summary>Xem phân bổ theo nhóm công việc và thư viện</summary><div class="table-scroll"><table class="simple-table"><thead><tr><th>Nhóm công việc</th><th>Dự thảo</th><th>Thử nghiệm</th><th>Đã duyệt</th></tr></thead><tbody>${S.all('groups').map(g=>`<tr><td>${btn(g.name,'tasks',{scope:'all',group:g.id},'text-btn')}</td>${C.useCaseStatuses.map(st=>`<td>${ucs.filter(u=>u.groupId===g.id&&u.status===st).length}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="status-line">${Object.keys(C.types).map(t=>badge(`${C.types[t].label}: ${sm.byType[t]} nội dung đang duy trì`)).join('')}</div><p class="chart-note">Tổng tiềm năng ước tính: ${nf(sm.saved)} giờ/tháng, gồm cả dự thảo và thử nghiệm. Không cộng số giờ của mẫu và agent liên quan để tránh tính trùng.</p></details>`;
  }

  function renderGuide(el) {
    el.innerHTML=pageHead('Bắt đầu cùng Copilot','Một công việc cụ thể, một mẫu phù hợp, một kết quả được kiểm tra.')+`<div class="workspace-grid"><div class="surface">${[['Chọn đúng công việc','Mở Công việc & phân công, chọn nhiệm vụ của bạn. Nếu chưa được phân công, có thể khám phá kho mẫu theo nhu cầu.','tasks','Mở công việc'],['Chọn mẫu hoặc trợ lý phù hợp','Xem kết quả mong muốn, tài liệu cần chuẩn bị và tình trạng nội dung. Mẫu câu lệnh dùng cho yêu cầu cụ thể; quy trình hướng dẫn nhiều bước; trợ lý hỗ trợ nhiệm vụ lặp lại.','catalog','Tìm mẫu'],['Thực hiện tại công cụ phù hợp','Sao chép mẫu và dùng trong Copilot theo hướng dẫn. Với trợ lý, chỉ mở khi đã có đường dẫn kết nối; các bản đang xây dựng có hướng dẫn thiết lập.','agents','Xem trợ lý'],['Kiểm tra trước khi sử dụng','Đối chiếu số liệu, điều khoản và thông tin với tài liệu nguồn. Ghi lại điểm cần làm tiếp, lưu mẫu hữu ích để tìm lại nhanh.','samples','Xem sản phẩm mẫu']].map(([t,d,r,b],i)=>`<div class="help-step"><div class="task-mark">0${i+1}</div><div><h3>${t}</h3><p>${d}</p>${btn(b+' →',r,{scope:'all'},'text-btn')}</div></div>`).join('')}</div><aside><div class="surface">${section('','Bạn đang cần gì?')}<div class="quick-list">${quick('Mẹo dùng Copilot','Hướng dẫn cho Word, Excel, Teams và công cụ khác','tips')}${quick('Xem sản phẩm mẫu','Hình dung đầu ra trước khi làm','samples')}${quick('Tìm người hỗ trợ','Người xây dựng và rà soát từng nội dung','support')}</div></div><div class="aside-note"><h3>Ban KSNB là điểm khởi đầu</h3><p>Nội dung hiện do Ban KSNB xây dựng. Danh mục lĩnh vực giúp phân loại chuyên môn và chuẩn bị mở rộng PVEP, không có nghĩa các đơn vị khác đã triển khai.</p></div></aside></div>`;
  }
  function renderSupport(el) {
    el.innerHTML=pageHead('Hỗ trợ sử dụng','Tìm đúng đầu mối theo mẫu và nhiệm vụ bạn đang sử dụng.')+`<div class="workspace-grid"><section class="surface">${section('01','Hỗ trợ theo nội dung')}<p class="workspace-note">Mở mẫu hoặc trợ lý → xem “Người xây dựng / hỗ trợ nội dung” và “Người rà soát”. App không tự gửi yêu cầu hỗ trợ.</p><div class="quick-list">${quick('Tìm mẫu cần hỗ trợ','Tra cứu theo tên nhiệm vụ và nhóm công việc','catalog',{scope:'all'})}${quick('Tìm trợ lý cần hỗ trợ','Xem người xây dựng và phạm vi dữ liệu','agents',{scope:'all'})}${quick('Danh sách cán bộ','Xem chức danh, nhóm công việc và phân công','people')}</div></section><section class="surface">${section('02','Câu hỏi thường gặp')}<details class="management-details" open><summary>Vì sao chưa thấy công việc của tôi?</summary><p class="workspace-note">Chọn đúng tên cán bộ ở góc trên. Nếu vẫn chưa có nhiệm vụ, xem công việc của Ban và trao đổi với đầu mối để cập nhật phân công.</p></details><details class="management-details"><summary>Nút “Sao chép” có chạy AI không?</summary><p class="workspace-note">Không. Nút sao chép lấy nội dung mẫu để bạn dùng tại công cụ phù hợp. App này chưa xử lý tài liệu bằng AI.</p></details><details class="management-details"><summary>“Đã duyệt” có nghĩa agent đã chạy được?</summary><p class="workspace-note">Đó là trạng thái nội dung. Trợ lý chỉ có nút mở khi đầu mối đã khai báo đường dẫn HTTPS và tình trạng triển khai tương ứng.</p></details><details class="management-details"><summary>Dữ liệu và ghi chú được lưu ở đâu?</summary><p class="workspace-note">Ở chế độ thí điểm hiện tại, dữ liệu được lưu trong trình duyệt trên máy này; không tự đồng bộ với máy khác. Có thể xuất dữ liệu trong khu vực Triển khai AI. Lựa chọn cán bộ không phải đăng nhập.</p></details></section></div>`;
  }
  function renderManage(el) {
    if(!person()||mode()!=='coordinator'){el.innerHTML=pageHead('Triển khai AI','Không gian của đầu mối xây dựng và duy trì thư viện.')+empty('Chuyển sang vai trò đầu mối để quản lý','Đây là lựa chọn giao diện trong bản thí điểm, chưa phải phân quyền tài khoản.','<button class="btn" data-profile>Chọn không gian làm việc</button>');return;}
    const lib=activeLib(), pending=lib.filter(x=>x.status==='Testing'), building=lib.filter(x=>x.status==='Draft'), agents=lib.filter(x=>x.type==='agent'), connected=agents.filter(x=>availability(x).url);
    el.innerHTML=pageHead('Triển khai AI tại Ban KSNB','Chuẩn hóa nội dung, kết nối trợ lý và từng bước mở rộng phạm vi PVEP.',btn('Xem lộ trình →','roadmap',null,'btn'))+`<div class="metrics">${metric('Nội dung đang xây dựng',building.length,'Mẫu, quy trình và trợ lý dự thảo')}${metric('Nội dung đang thử nghiệm',pending.length,'Cần tiếp tục rà soát')}${metric('Trợ lý có đường dẫn',connected.length,`Trên ${agents.length} trợ lý đang duy trì`)}${metric('Lĩnh vực phân loại',C.domains.length,'Chưa phải số đơn vị đã triển khai')}</div><section class="surface">${section('01','Ưu tiên hoàn thiện')}<div class="table-scroll"><table class="simple-table"><thead><tr><th>Nội dung</th><th>Người xây dựng</th><th>Người rà soát</th><th>Hạn</th><th>Trạng thái</th></tr></thead><tbody>${[...pending,...building].sort((a,b)=>String(a.deadline||'9999').localeCompare(b.deadline||'9999')).map(x=>`<tr><td class="name-cell"><button class="task-name" data-resource="${esc(x.id)}">${esc(nameOf(x))}</button><small>${esc(kindOf(x))}</small></td><td>${esc(U.pname(x.builderId))}</td><td>${esc(U.pname(x.reviewerId))}</td><td>${U.date(x.deadline)}</td><td>${U.status(x.status)}</td></tr>`).join('')||'<tr><td colspan="5">Chưa có nội dung cần hoàn thiện.</td></tr>'}</tbody></table></div><div class="btn-row" style="margin-top:18px"><button class="btn" data-add-resource="prompt">+ Mẫu câu lệnh</button><button class="btn" data-add-resource="skill">+ Quy trình từng bước</button><button class="btn" data-add-resource="agent">+ Trợ lý</button>${btn('Bảng quản lý công việc','register',null,'btn')}</div></section><div class="block-space">${section('02','Phạm vi triển khai & lĩnh vực PVEP','', 'Ban KSNB là đơn vị thí điểm. Các lĩnh vực dưới đây dùng phân loại nội dung hiện có của Ban.')}<div class="domain-grid">${C.domains.map(d=>{const n=lib.filter(x=>x.domainId===d.id).length;return `<div class="domain-tile"><h4>${esc(d.name)}</h4>${badge(n?`${n} nội dung của Ban KSNB`:'Chưa có nội dung',n?'green':'gray')}<p style="margin-top:8px">${n?'Có thể tra cứu theo lĩnh vực.':'Sẵn cấu trúc phân loại khi mở rộng.'}</p>${n?btn('Xem nội dung →','catalog',{scope:'domain',domain:d.id},'text-btn'):''}</div>`;}).join('')}</div></div><div class="callout"><div><strong>Lộ trình mở rộng</strong><br>Thử nghiệm tại Ban KSNB → Đánh giá kết quả và chuẩn hóa mẫu → Bổ sung đơn vị, cán bộ và nội dung theo lĩnh vực. Khi triển khai nhiều đơn vị, cần tài khoản, quyền truy cập và kho dữ liệu dùng chung.</div></div><section class="surface block-space">${section('03','Dữ liệu của bản thí điểm')}<p class="workspace-note">Xuất bản sao trước khi chuyển máy hoặc thay phiên bản. Tệp JSON chứa dữ liệu công việc, cán bộ và thư viện; lựa chọn cá nhân và ghi chú có tệp sao lưu riêng.</p><div class="btn-row"><button class="btn primary" data-export>Xuất dữ liệu JSON</button><button class="btn" data-import>Nhập dữ liệu JSON</button><button class="btn" data-export-personal>Sao lưu lựa chọn & ghi chú</button><button class="btn" data-import-personal>Khôi phục lựa chọn & ghi chú</button></div><input type="file" id="workspaceImport" accept=".json" hidden><input type="file" id="personalImport" accept=".json" hidden></section>`;
    U.$('#workspaceImport',el).onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const text=await f.text();const obj=JSON.parse(text);if(!AIM.COLLECTIONS.every(k=>Array.isArray(obj[k])))throw new Error('Tệp chưa có đầy đủ các danh mục dữ liệu.');if(!confirm('Nhập tệp sẽ thay dữ liệu hiện có trên trình duyệt. Bạn đã xuất bản sao và muốn tiếp tục?'))return;await S.importJSON(text);U.toast('Đã nhập dữ liệu.');}catch(err){alert('Không nhập được: '+err.message);}finally{e.target.value='';}};
    U.$('#personalImport',el).onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const obj=JSON.parse(await f.text());if(obj.format!=='pvep-workspace-preferences-v2'||!obj.preferences||typeof obj.preferences!=='object'||Array.isArray(obj.preferences))throw new Error('Không phải tệp sao lưu lựa chọn của app.');if(!confirm('Khôi phục sẽ thay lựa chọn và ghi chú cá nhân trên trình duyệt này. Tiếp tục?'))return;pref=obj.preferences;persist();render();U.toast('Đã khôi phục lựa chọn và ghi chú.');}catch(err){alert(err.message);}finally{e.target.value='';}};
  }
  function editDeployment(id) {
    if(!canEdit())return;
    const x=S.get('library',id);if(!x)return;
    const fields=[{k:'displayName',label:'Tên ngắn theo công việc',span:2},{k:'launchUrl',label:'Đường dẫn mở trợ lý (HTTPS)',span:2},{k:'deployment',label:'Tình trạng triển khai',type:'select',options:[['planned','Chưa kết nối / đang xây dựng'],['trial','Có bản thử nghiệm'],['ready','Đã triển khai sử dụng']]},{k:'status',label:'Trạng thái nội dung',type:'select',options:U.statusOpts(C.libraryStatuses)}];
    const p=U.modal({wide:true,title:'Nơi sử dụng · '+esc(nameOf(x)),body:'<div class="callout">Chỉ khai báo đường dẫn của trợ lý đã được thiết lập. App không tự tạo agent hay kết nối nguồn dữ liệu.</div>'+U.form(fields,{...x,displayName:nameOf(x),deployment:x.deployment||'planned'})+'<p id="deploymentError" role="alert" style="color:#a0472a;font-size:12px"></p>',foot:'<button class="btn" data-close>Hủy</button><button class="btn primary" data-save-deployment>Lưu cấu hình</button>'});
    U.$('[data-save-deployment]',p).onclick=async()=>{const next=U.readForm(p,fields,x);next.launchUrl=(next.launchUrl||'').trim();let error='';if(next.launchUrl&&!safeURL(next.launchUrl))error='Nhập đường dẫn HTTPS hợp lệ.';else if(next.deployment!=='planned'&&!next.launchUrl)error='Cần đường dẫn để mở bản thử nghiệm hoặc trợ lý đã triển khai.';else if(next.deployment==='ready'&&next.status!=='Approved')error='Trợ lý triển khai sử dụng cần có nội dung đã duyệt.';else if(next.deployment==='trial'&&!['Testing','Approved'].includes(next.status))error='Bản thử nghiệm cần trạng thái nội dung Thử nghiệm hoặc Đã duyệt.';if(error){U.$('#deploymentError',p).textContent=error;return;}try{await S.save('library',next);U.close();U.toast('Đã lưu nơi sử dụng trợ lý.');}catch(err){U.$('#deploymentError',p).textContent='Chưa lưu được: '+err.message;}};
  }
  function quickContext() {
    const resource=current.key==='resource'?S.get('library',current.params.id):null;
    const task=current.key==='task'?S.get('useCases',current.params.id):resource?S.get('useCases',resource.useCaseId):null;
    return {task,resource,group:task?.groupId||resource?.groupId||current.params.group||'',title:task?.task||resource?.name||views[current.key]?.title||'Ban KSNB'};
  }
  function relevance(x,ctx) {
    if(ctx.task&&x.useCaseId===ctx.task.id)return 3;
    if(ctx.resource&&x.id===ctx.resource.id)return 3;
    if(ctx.group&&x.groupId===ctx.group)return 2;
    if(related(x))return 1;
    return 0;
  }
  function quickSearch(q,scope='context',ctx=quickContext()) {
    const query=normalize(q).trim();
    const tokens=query.split(/\s+/).filter(Boolean);
    function score(text) {const hay=normalize(text);if(!query)return 1;if(hay.includes(query))return 30+tokens.length;const hits=tokens.filter(t=>hay.includes(t)).length;return hits===tokens.length?hits:0;}
    let rows=activeLib().map(x=>({id:x.id,kind:x.type==='agent'?'Trợ lý':kindOf(x),title:nameOf(x),text:x.purpose||x.output||'',resource:x,rank:relevance(x,ctx),score:score([nameOf(x),x.name,x.purpose,x.output,U.group(x.groupId).name,U.domain(x.domainId).name,x.instruction].join(' '))}));
    rows=rows.filter(r=>r.score>0&&(scope==='all'||r.rank>0));
    if(query&&scope==='all'){
      rows.push(...S.all('useCases').map(u=>({id:u.id,kind:'Công việc',title:u.task,text:u.aiStep||u.next||'',task:u,rank:mine(u)?1:0,score:score([u.task,u.aiStep,u.next,U.group(u.groupId).name].join(' '))})).filter(r=>r.score>0));
      rows.push(...S.all('tips').map(t=>({id:t.id,kind:'Hướng dẫn',title:t.title,text:t.why||'',tip:t,rank:0,score:score([t.title,t.why,...(t.how||[])].join(' '))})).filter(r=>r.score>0));
    }
    return rows.sort((a,b)=>(query?b.score-a.score:0)||b.rank-a.rank||(b.resource?.type==='agent')-(a.resource?.type==='agent')||a.title.localeCompare(b.title,'vi'));
  }
  function openQuickAI() {
    const ctx=quickContext();let scope=person()||ctx.task||ctx.resource?'context':'all';
    const p=U.drawer({title:'Tra nhanh AI',sub:`<span>Đang xem: ${esc(ctx.title)}</span>`,body:`<p class="quick-intro">Tìm trợ lý, mẫu và hướng dẫn ngay tại công việc đang xem.</p><div class="searchbox"><label for="quickAIQuery">Bạn cần hỗ trợ việc gì?</label><input id="quickAIQuery" type="search" placeholder="Ví dụ: hồ sơ kiểm tra, quy chế, tờ trình…" autocomplete="off"></div><div class="tabs quick-tabs"><button data-quick-scope="context" class="${scope==='context'?'active':''}">Liên quan trang này</button><button data-quick-scope="all" class="${scope==='all'?'active':''}">Toàn bộ Ban KSNB</button></div><div class="quick-suggestions">${['Quy chế','Hồ sơ','Tờ trình','Chỉ đạo'].map(q=>`<button data-quick-query="${q}">${q}</button>`).join('')}</div><div id="quickAIResults" aria-live="polite"></div><div class="quick-disclosure">Tra cứu nội dung hiện có trong app, không tự sinh câu trả lời hoặc đọc hồ sơ. Trợ lý đã kết nối sẽ mở tại công cụ đích.</div>`,foot:'<button class="btn" data-route="agents" data-params="{&quot;scope&quot;:&quot;all&quot;}">Mở kho trợ lý</button><button class="btn" data-close>Đóng</button>'});
    const draw=()=>{
      const rows=quickSearch(U.$('#quickAIQuery',p).value,scope,ctx),list=rows.slice(0,10);
      U.$('#quickAIResults',p).innerHTML=`<div class="result-meta">${rows.length} kết quả${rows.length>10?' · hiển thị 10 mục đầu':''}</div>`+(list.length?list.map(r=>{const a=r.resource?availability(r.resource):null;return `<article class="quick-result"><div class="status-line">${badge(r.kind)}${r.rank===3?badge('Cùng nhiệm vụ','green'):r.rank===2?badge('Cùng nhóm công việc'):''}</div><h4>${esc(r.title)}</h4><p>${esc(r.text)}</p>${a?`<div class="status-line">${badge(a.label,a.class)}</div>`:''}<div class="btn-row">${a?.url?`<a class="btn primary sm" href="${esc(a.url)}" target="_blank" rel="noopener noreferrer">${esc(a.action)} ↗</a>`:''}${r.resource?`<button class="text-btn" data-resource="${esc(r.id)}">${r.resource.type==='agent'&&!a.url?'Xem hướng dẫn & tình trạng':'Xem cách sử dụng'} →</button>`:r.task?`<button class="text-btn" data-task="${esc(r.id)}">Mở công việc →</button>`:`<button class="text-btn" data-tip-detail="${esc(r.id)}">Đọc hướng dẫn →</button>`}</div></article>`;}).join(''):empty('Chưa có kết quả phù hợp',scope==='context'?'Thử tìm trong toàn bộ Ban hoặc dùng từ khóa ngắn hơn.':'Thử từ khóa khác, ví dụ “quy chế” hoặc “hồ sơ”.','<button class="btn" data-quick-all>Tìm trong toàn bộ Ban</button>'));
    };
    U.$('#quickAIQuery',p).addEventListener('input',draw);
    p.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.quickScope){scope=b.dataset.quickScope;draw();}if(b.dataset.quickQuery){scope='all';U.$('#quickAIQuery',p).value=b.dataset.quickQuery;draw();}if(b.hasAttribute('data-quick-all')){scope='all';draw();}U.$$('[data-quick-scope]',p).forEach(x=>x.classList.toggle('active',x.dataset.quickScope===scope));});
    draw();
  }
  function openTip(id) {
    const t=S.get('tips',id);if(!t)return;
    U.drawer({title:esc(t.title),sub:'<span>Hướng dẫn trong thư viện Ban KSNB</span>',body:`<p class="workspace-note">${esc(t.why)}</p><ol class="quick-how">${(t.how||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ol>${t.avoid?`<div class="callout warning">${esc(t.avoid)}</div>`:''}${t.sample?`<h4>Câu lệnh mẫu</h4><pre class="readable-prompt">${esc(t.sample)}</pre><button class="btn" data-copy-tip="${esc(t.id)}">Sao chép câu lệnh</button>`:''}`,foot:'<button class="btn" data-quick-ai>← Tra nhanh AI</button><button class="btn" data-close>Đóng</button>'});
  }
  const views = {
    home:{title:'Trang của tôi',render:renderHome}, tasks:{title:'Công việc',render:renderTasks}, task:{title:'Chi tiết công việc',render:renderTask},
    catalog:{title:'Kho mẫu AI',render:renderCatalog}, resource:{title:'Hướng dẫn sử dụng',render:renderResource}, agents:{title:'Trợ lý công việc',render:(el,p)=>renderCatalog(el,p,true)},
    dashboard:{title:'Điều hành',render:renderDashboard}, guide:{title:'Hướng dẫn',render:renderGuide}, support:{title:'Hỗ trợ',render:renderSupport}, manage:{title:'Triển khai AI',render:renderManage},
    people:AIM.views.people, tips:AIM.views.tips, samples:AIM.views.samples, roadmap:AIM.views.roadmap,
    register:{title:'Bảng quản lý đầy đủ',render:(el,p)=>legacy.usecases.render(el,p)}, agentmap:{title:'Sơ đồ hệ thống trợ lý',render:(el,p)=>{legacy.agents.render(el,p);const n=el.querySelector('.phd h2');if(n)n.textContent='Sơ đồ hệ thống trợ lý';}},
    prompts:{title:'Mẫu câu lệnh',render:(el,p)=>renderCatalog(el,{...p,type:'prompt'})}, skills:{title:'Quy trình từng bước',render:(el,p)=>renderCatalog(el,{...p,type:'skill'})}, usecases:{title:'Công việc',render:renderTasks}
  };
  Object.assign(AIM.views,views);
  function parseHash() { const [raw,qs]=location.hash.replace(/^#\/?/,'').split('?');const aliases={usecases:'tasks',prompts:'catalog',skills:'catalog'};let key=aliases[raw]||raw;const params=Object.fromEntries(new URLSearchParams(qs||''));if(raw==='prompts')params.type='prompt';if(raw==='skills')params.type='skill';return {key:views[key]?key:'home',params}; }
  function go(key,params) { U.close();const qs=params?new URLSearchParams(params).toString():'';const next='#/'+key+(qs?'?'+qs:'');if(location.hash===next){render();window.scrollTo(0,0);}else location.hash=next; }
  const navigation = [['home','Trang của tôi','dashboard'],['tasks','Công việc','usecases'],['catalog','Kho mẫu AI','prompts'],['agents','Trợ lý công việc','agents'],['guide','Hướng dẫn','tips']];
  function shell() {
    const p=person(), roleName={staff:'Chuyên viên',lead:'Lãnh đạo',coordinator:'Đầu mối AI'}[mode()];
    U.$('header.top').innerHTML=`<div class="hwrap"><button class="menu-toggle" aria-label="Mở menu" aria-expanded="${document.body.classList.contains('nav-open')}" data-toggle-menu>☰</button><div class="brand"><img src="${window.PVEP_ASSETS['logo.png']}" alt="Petrovietnam PVEP"><div><h1>COPILOT HUB PVEP</h1><div class="unit">BAN KIỂM SOÁT NỘI BỘ</div></div></div><div class="hdtools"><div class="header-context"><span class="pilot-dot"></span>Không gian thí điểm <b>KSNB</b></div><button class="profile-btn" data-profile aria-label="Chọn cán bộ và không gian làm việc"><span class="av">${esc(U.initials(p?.name||'KS'))}</span><span class="person-name">${esc(p?.name||'Chọn cán bộ')}<small>${p?roleName:'Cá nhân hóa công việc'}⌄</small></span></button></div></div>`;
    const navItem=([key,label,ico])=>`<button data-route="${key}" class="${current.key===key||(key==='catalog'&&current.key==='resource')||(key==='tasks'&&current.key==='task')?'active':''}" ${current.key===key?'aria-current="page"':''}>${icon(ico)}<span>${label}</span>${key==='agents'?`<em class="cnt">${activeLib().filter(x=>x.type==='agent').length}</em>`:''}</button>`;
    U.$('aside.side').innerHTML=`<button class="mobile-close" data-toggle-menu>Đóng menu ×</button><div class="navlbl">Không gian làm việc</div><nav class="menu" aria-label="Điều hướng chính">${navigation.map(navItem).join('')}${isManager()?`<div class="navgroup">Điều hành & triển khai</div>${[['dashboard','Điều hành','dashboard'],['people','Cán bộ & phân công','people'],['roadmap','Lộ trình','roadmap'],...(mode()==='coordinator'?[['manage','Triển khai AI','skills']]:[])].map(navItem).join('')}`:''}</nav><div class="sidefoot"><strong><span class="pilot-dot"></span>Ban KSNB · PVEP</strong><p>Thí điểm theo nhiệm vụ.<br>Hướng tới các lĩnh vực PVEP.</p><button class="side-help" data-route="support">Hỗ trợ sử dụng ↗</button></div>`;
    document.body.classList.toggle('ro',!canEdit());
  }
  function render() {
    if(!booted)return;
    if(pref.person&&!person()){delete pref.person;delete pref.mode;persist();}
    current=parseHash();shell();
    const el=U.$('#main');
    el.innerHTML=`<div class="breadcrumb">PVEP<span>/</span>Ban KSNB<span>/</span>${esc(views[current.key].title)}</div><section class="view" id="workspaceView"></section><footer class="foot"><span>PVEP · Ban Kiểm soát nội bộ</span><span>${S.mode()==='local'?'Bản thí điểm · dữ liệu lưu trên trình duyệt':'Dữ liệu từ hệ thống kết nối'} · Ngày tham chiếu ${U.date(L.iso(L.today()))}</span></footer>`;
    try{views[current.key].render(U.$('#workspaceView'),current.params);}catch(err){console.error(err);U.$('#workspaceView').innerHTML=empty('Chưa mở được nội dung','Dữ liệu có thể chưa đầy đủ. Quay lại trang của tôi hoặc kiểm tra tệp dữ liệu.',btn('Trang của tôi','home'));}
    if(!U.$('#quickAIFab'))document.body.insertAdjacentHTML('beforeend',`<button id="quickAIFab" class="quick-ai-fab" data-quick-ai aria-label="Tra nhanh AI theo công việc đang xem"><span aria-hidden="true">${icon('agents')}</span><span>Tra nhanh AI</span><span class="fab-arrow" aria-hidden="true">↗</span></button>`);
    const ctx=quickContext();
    if(ctx.task){const linked=agentsForTask(ctx.task.id);if(linked.length){const spot=U.$('.page-head',U.$('#workspaceView'));if(spot)spot.insertAdjacentHTML('afterend',`<div class="context-ai-strip"><div><b>Trợ lý gắn với nhiệm vụ này</b><span>${linked.map(x=>esc(nameOf(x))).join(' · ')}</span></div><button class="btn" data-quick-ai>Tra nhanh ngay ↗</button></div>`);}}
    document.title=views[current.key].title+' · Copilot Hub PVEP / KSNB';
    document.body.classList.remove('nav-open');
  }
  function refresh(){const y=scrollY;render();scrollTo(0,y);}
  async function onClick(e) {
    const b=e.target.closest('button,a'); if(!b||b.disabled)return;
    if(b.hasAttribute('data-toggle-menu')){document.body.classList.toggle('nav-open');const t=U.$('[data-toggle-menu]');if(t)t.setAttribute('aria-expanded',document.body.classList.contains('nav-open'));return;}
    if(b.hasAttribute('data-profile'))return selectProfile();
    if(b.hasAttribute('data-quick-ai'))return openQuickAI();
    if(b.dataset.tipDetail)return openTip(b.dataset.tipDetail);
    if(b.dataset.copyTip){const t=S.get('tips',b.dataset.copyTip);if(t)return U.copy(t.sample||'');}
    if(b.hasAttribute('data-save-profile')) {
      const id=U.$('#choose-person').value;if(!id){U.$('#choose-person').focus();U.toast('Chọn cán bộ trước khi tiếp tục.');return;}
      pref.person=id;const selected=U.$('#choose-mode').value;pref.mode=selected==='auto'?(S.get('people',id)?.isLead?'lead':'staff'):selected;persist();U.close();go('home');return;
    }
    if(b.dataset.route){let params;try{params=JSON.parse(b.dataset.params||'{}');}catch(_){params={};}return go(b.dataset.route,params);}
    if(b.dataset.task)return go('task',{id:b.dataset.task});
    if(b.dataset.resource)return go('resource',{id:b.dataset.resource});
    if(b.dataset.favorite){if(!person()){selectProfile();return;}const p=personal(),id=b.dataset.favorite;p.favorites=p.favorites||[];const had=p.favorites.includes(id);p.favorites=had?p.favorites.filter(x=>x!==id):[...p.favorites,id];persist();document.querySelectorAll('[data-favorite]').forEach(x=>{if(x.dataset.favorite!==id)return;x.setAttribute('aria-pressed',!had);x.classList.toggle('on',!had);x.textContent=x.classList.contains('favorite')?(!had?'★':'☆'):(!had?'★ Đã lưu':'☆ Lưu để dùng lại');x.setAttribute('aria-label',(!had?'Bỏ lưu ':'Lưu ')+nameOf(S.get('library',id)));});U.toast(had?'Đã bỏ lưu.':'Đã lưu để dùng lại.');return;}
    if(b.dataset.copyInstruction){const x=S.get('library',b.dataset.copyInstruction);if(x&&x.status!=='Deprecated')return U.copy(x.instruction||'');}
    if(b.dataset.saveDraft){if(!person()){selectProfile();return;}const p=personal();p.drafts=p.drafts||{};p.drafts[b.dataset.saveDraft]={note:U.$('#resourceNote').value,checks:U.$$('[data-check]:checked').map(x=>+x.dataset.check),updated:new Date().toISOString()};persist();U.$('#draftStatus').textContent='Đã lưu ghi chú và bước chuẩn bị cho '+person().name+'.';return;}
    if(b.dataset.technicalTask)return legacy.usecases.open(b.dataset.technicalTask);
    if(b.dataset.editTask&&canEdit())return legacy.usecases.edit(S.get('useCases',b.dataset.editTask));
    if(b.hasAttribute('data-add-task')&&canEdit())return legacy.usecases.edit(null);
    if(b.dataset.editResource&&canEdit())return AIM.lib.edit(S.get('library',b.dataset.editResource));
    if(b.dataset.addResource&&canEdit())return AIM.lib.edit(null,b.dataset.addResource);
    if(b.dataset.deployment&&canEdit())return editDeployment(b.dataset.deployment);
    if(b.dataset.deleteResource&&canEdit()){const x=S.get('library',b.dataset.deleteResource);if(x&&confirm('Xóa nội dung '+x.name+'? Bạn có thể chọn Ngừng dùng trong Sửa nội dung để giữ lịch sử.')){await S.remove('library',x.id);go(x.type==='agent'?'agents':'catalog',{scope:'all'});}return;}
    if(b.hasAttribute('data-export'))return U.download('pvep-ksnb-'+L.iso(L.today())+'.json',S.exportJSON());
    if(b.hasAttribute('data-import'))return U.$('#workspaceImport')?.click();
    if(b.hasAttribute('data-export-personal'))return U.download('pvep-ksnb-lua-chon-ca-nhan.json',JSON.stringify({format:'pvep-workspace-preferences-v2',preferences:pref},null,2));
    if(b.hasAttribute('data-import-personal'))return U.$('#personalImport')?.click();
    if(b.hasAttribute('data-clear-filters'))return go(current.key==='agents'?'agents':'catalog',{scope:'all'});
  }
  async function start() {
    document.documentElement.style.setProperty('--rig-image',`url("${window.PVEP_ASSETS['rig.webp']}")`);
    document.documentElement.style.setProperty('--logo-image',`url("${window.PVEP_ASSETS['logo.png']}")`);
    const fav=U.$('link[rel="icon"]');if(fav)fav.href=window.PVEP_ASSETS['logo.png'];
    document.body.insertAdjacentHTML('afterbegin','<a class="skip-link" href="#main">Đi tới nội dung</a>');
    U.$('#main').setAttribute('tabindex','-1');
    U.initTip();
    try{await S.init();}catch(err){U.$('#main').innerHTML=empty('Chưa tải được dữ liệu','Kiểm tra kết nối hệ thống hoặc nguồn dữ liệu đã cấu hình.');console.error(err);return;}
    booted=true;
    document.addEventListener('click',e=>{onClick(e).catch(err=>{console.error(err);U.toast('Chưa thực hiện được thao tác. Vui lòng thử lại.');});});
    window.addEventListener('hashchange',()=>{U.close();render();scrollTo(0,0);});
    S.subscribe(()=>refresh());render();
  }
  AIM.workspace={person,mode,related,availability,safeURL,nameOf,render,go,quickSearch,agentsForTask};
  AIM.app={start,go,canEdit,refresh,current:()=>current};
  AIM.lib.open=id=>go('resource',{id});
  AIM.views.usecases.open=id=>go('task',{id});
})();
